import{_ as n,o as a,c as i,a6 as o}from"./chunks/framework.DL_pga9_.js";const h=JSON.parse('{"title":"const fun And Compile-Time Computation","description":"","frontmatter":{},"headers":[],"relativePath":"design/archive/const_fun.md","filePath":"design/archive/const_fun.md","lastUpdated":1780030916000}'),t={name:"design/archive/const_fun.md"};function s(c,e,l,r,d,p){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="const-fun-and-compile-time-computation" tabindex="-1"><code>const fun</code> And Compile-Time Computation <a class="header-anchor" href="#const-fun-and-compile-time-computation" aria-label="Permalink to “const fun And Compile-Time Computation”">​</a></h1><h2 id="order" tabindex="-1">Order <a class="header-anchor" href="#order" aria-label="Permalink to “Order”">​</a></h2><p>Recommended Issue order: 6.</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “Goal”">​</a></h2><p>Introduce compile-time executable functions for use in <code>const</code> definitions, <code>where</code> predicates, const generic arguments, and <code>const if</code>.</p><p>Example direction:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>const fun is_power_of_two(value: u32) -&gt; bool {</span></span>
<span class="line"><span>  ...</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fun foo&lt;const N: u32&gt;() where is_power_of_two(N) {</span></span>
<span class="line"><span>  ...</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to “Dependencies”">​</a></h2><p>Prerequisites:</p><ul><li><a href="./constant_generic_parameters">Constant Generic Parameters</a>, for const values in generic signatures and mangling.</li><li>Existing const predicates and <code>const if</code>.</li></ul><p>Unblocks:</p><ul><li>Full <a href="./../enhanced_tuples">Enhanced Tuple Types</a>, especially recursive <code>tuple_element</code> and const arithmetic over tuple indexes.</li><li>More expressive type/const constraints.</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>In scope:</p><ul><li><code>const fun</code> declaration syntax.</li><li>A restricted compile-time evaluator.</li><li>Deterministic, side-effect-free execution.</li><li>Scalar return values initially: <code>bool</code>, integers, and <code>string</code> if needed.</li><li>Calls from const definitions, <code>where</code> predicates, and <code>const if</code>.</li><li>Runtime calls from non-const contexts. In that mode, <code>const fun</code> behaves like a normal <code>fun</code>; <code>const</code> means compile-time capable, not compile-time only.</li><li>Recursion and loop limits with explicit diagnostics.</li><li>Function body execution should reuse the STUPID interpreter through a restricted const runner; the type checker owns const-safety checks and scalar value marshalling, not a second evaluator.</li></ul><p>Out of scope:</p><ul><li>Runtime reflection.</li><li>IO, native side effects, allocation-heavy compile-time execution.</li><li>Type-level associated types.</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to “Acceptance Criteria”">​</a></h2><ul><li><code>const fun</code> can compute bool/integer scalar values.</li><li><code>where const_fun&lt;T&gt;()</code> or <code>where const_fun(N)</code> evaluates during type checking.</li><li>Non-terminating or over-limit compile-time execution reports a deterministic error.</li><li>Non-const functions cannot be called from const contexts.</li><li>Non-const runtime calls such as <code>val bar = foo(x)</code> are allowed when <code>foo</code> is a <code>const fun</code>.</li><li>Compile-time evaluator has tests for branching, loops, recursion limit, and invalid side effects.</li></ul>`,19)])])}const m=n(t,[["render",s]]);export{h as __pageData,m as default};
